import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """Parses an INI dialect string and returns a dictionary."""

    result: dict[str, dict[str, str]] = {}
    default_section: dict[str, str] = {}
    current_section: str | None = None
    previous_value: str | None = None

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(';') or line.startswith('#'):
            if previous_value is not None:
                previous_value = None
            continue

        match = re.match(r"^\s*\[(\w+)\]\s*$", line)
        if match:
            if current_section is not None:
                result[current_section] = section
            current_section = match.group(1)
            if current_section == "DEFAULT":
                section = default_section
            else:
                section = {}
                result[current_section] = section
            previous_value = None
            continue

        match = re.match(r"^(\w+)\s*(=|:)\s*(.*)$", line)
        if match:
            key = match.group(1).strip().lower()
            sep = match.group(2)
            value = match.group(3).strip()

            if current_section is None:
                raise ValueError("Key line before section header")

            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]
            else:
                value = interpolate(value, result, current_section)

            section[key] = value
            previous_value = value
            continue

        if previous_value is not None:
            if line.startswith(" "):
                previous_value += "\n" + line.strip()
            else:
                previous_value = None
        else:
            raise ValueError("Malformed line")

    if current_section is not None:
        result[current_section] = section

    # Merge DEFAULT section into other sections
    for key, value in default_section.items():
        for section_name, section in result.items():
            if section_name != "DEFAULT" and key not in section:
                section[key] = value

    return result


def interpolate(value: str, result: dict[str, dict[str, str]], current_section: str) -> str:
    """Interpolates variables in a value."""

    while True:
        match = re.search(r"\${(\w+)}", value)
        if not match:
            break

        key = match.group(1)
        try:
            if current_section == "DEFAULT":
                replacement = result["DEFAULT"].get(key)
            else:
                replacement = result[current_section].get(key)
            if replacement is None:
                raise KeyError(f"Key '{key}' not found")
            value = value.replace("${" + key + "}", replacement, 1)
        except KeyError as e:
            raise e
        except ValueError as e:
            raise e


    match = re.search(r"\${(\w+):(\w+)}", value)
    if match:
        section = match.group(1)
        key = match.group(2)
        try:
            if section not in result:
                raise KeyError(f"Section '{section}' not found")
            replacement = result[section].get(key)
            if replacement is None:
                raise KeyError(f"Key '{key}' not found in section '{section}'")

            value = value.replace("${" + section + ":" + key + "}", replacement, 1)
        except KeyError as e:
            raise e
        except ValueError as e:
            raise e

    return value
