from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        if capacity < 0:
            raise ValueError("Capacity must be non-negative")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def put(self, key, value):
        now = self.clock()
        if self.capacity == 0:
            return

        if key in self.cache:
            self.cache.move_to_end(key)
            self.cache[key] = (value, now + self.ttl)
        else:
            while len(self.cache) >= self.capacity:
                self._remove_expired()
                if len(self.cache) >= self.capacity:
                    self.evictions += 1
                    self.cache.popitem(last=False)  # LRU eviction

            self.cache[key] = (value, now + self.ttl)

    def get(self, key, default=None):
        now = self.clock()
        if self.capacity == 0:
            self.misses += 1
            return default

        if key in self.cache:
            value, expiry = self.cache.pop(key)
            if now >= expiry:
                self.expirations += 1
                self.misses += 1
                return default
            else:
                self.cache[key] = (value, now + self.ttl)
                self.cache.move_to_end(key)
                self.hits += 1
                return value
        else:
            self.misses += 1
            return default

    def __len__(self):
        now = self.clock()
        count = 0
        temp_cache = OrderedDict()
        for key, (value, expiry) in self.cache.items():
            if now < expiry:
                count += 1
                temp_cache[key] = (value, expiry)
        self.cache = temp_cache
        return count

    def stats(self):
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }

    def _remove_expired(self):
        now = self.clock()
        keys_to_remove = []
        for key, (value, expiry) in self.cache.items():
            if now >= expiry:
                keys_to_remove.append(key)

        for key in keys_to_remove:
            self.cache.pop(key)
            self.expirations += 1
