def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums.sort()
    unique_nums = []
    for num in nums:
        if not unique_nums or num != unique_nums[-1]:
            unique_nums.append(num)

    result = []
    i = 0
    while i < len(unique_nums):
        start = unique_nums[i]
        j = i + 1
        while j < len(unique_nums) and unique_nums[j] == unique_nums[j - 1] + 1:
            j += 1

        if j - i >= 3:
            result.append(f"{start}..{unique_nums[j - 1]}")
        elif j - i == 2:
            result.append(f"{start},{unique_nums[j - 1]}")
        else:
            result.append(str(start))

        i = j

    return ",".join(result)
