def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customer_totals = {}
    for row in rows:
        customer = row.get("customer")
        amount_str = row.get("amount")

        if not customer or not amount_str:
            continue

        customer = customer.strip()
        if not customer:
            continue

        try:
            amount = float(amount_str.replace("$", "").replace(",", ""))
        except ValueError:
            continue

        if customer not in customer_totals:
            customer_totals[customer] = 0.0

        customer_totals[customer] += amount

    sorted_customers = sorted(
        customer_totals.items(),
        key=lambda item: (-item[1], item[0]),
    )

    return sorted_customers[:n]
